details.zswapOutputNew:
/**
   * Creates a new output, targeted to a user's coin public key.
   *
   * Optionally the output contains a ciphertext encrypted to the user's
   * encryption public key, which may be omitted *only* if the {@link ShieldedCoinInfo}
   * is transferred to the recipient another way
   */
  static new(coin: ShieldedCoinInfo, segment: number | undefined, target_cpk: CoinPublicKey, target_epk: EncPublicKey): UnprovenOutput;

details.additionalCoinEncPublicKeyMappings:
/**
     * An optional mapping of {@link CoinPublicKey} to {@link EncPublicKey} that can be used to resolve encryption
     * keys for coins created during circuit execution.
     */
    readonly additionalCoinEncPublicKeyMappings?: ReadonlyMap<CoinPublicKey, EncPublicKey>;

details.resolverRefusal:
const createZswapOutput = ({ coinInfo, recipient }, encryptionPublicKeyResolver, segmentNumber = 0) => {
    if (!recipient.is_left) {
        return ZswapOutput.newContractOwned(coinInfo, segmentNumber, recipient.right);
    }
    const encryptionPublicKey = encryptionPublicKeyResolver(recipient.left);
    if (!encryptionPublicKey) {
        throw new Error(`Unable to resolve encryption public key for recipient ${recipient.left}. ` +
            `Provide a mapping via the encryptionPublicKeyResolver.`);
    }
